(x, y, t) => {
  const cx = 240, cy = 120;
  const wx1 = Math.sin(x*0.015+t*0.3)*20 + Math.cos(y*0.02-t*0.25)*15;
  const wy1 = Math.cos(y*0.015-t*0.28)*20 + Math.sin(x*0.018+t*0.32)*15;
  const wx2 = Math.sin((x+wx1)*0.025-t*0.4)*8 + Math.cos((y+wy1)*0.03+t*0.35)*6;
  const wy2 = Math.cos((y+wy1)*0.025+t*0.38)*8 + Math.sin((x+wx1)*0.028-t*0.42)*6;
  const sx = x+wx1+wx2, sy = y+wy1+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*60,40+Math.cos(t*0.65+1)*50,0.11,2.1],
    [400+Math.cos(t*0.55+2)*70,200+Math.sin(t*0.75)*60,0.085,1.8]
  ];
  let aS=0,iS=0,hrm=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    hrm+=Math.cos(d*f*1.3-t*sp*0.8+2.0)*0.5;
  }
  const act=aS/8,inh=iS/8,hr=hrm/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.06+Math.sin(sy*0.05+t)*2+t*1.5)*0.15+Math.cos(sy*0.055+Math.cos(sx*0.045-t)*2+t*1.3)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2=Math.sin(dist*0.08+ang*2-t*2.0)*Math.cos(dist*0.06-ang*5+t*1.8)*0.2;
  const u=act-inh*0.7+bg*0.3+spiral+spiral2;
  const vC=hr*0.6+Math.sin(act*2.0+inh*1.5+t*0.5)*0.4;
  const wC=Math.sin(dist*0.03+ang-t*0.8)*0.3+Math.cos(act-inh+t)*0.2;
  const reaction=Math.tanh(u*2.2),dV=Math.tanh(vC*1.8),dW=Math.tanh(wC*1.5);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const feedback=Math.sin(reaction*3.0+dV*2.0)*0.1;
  const blend=reaction*0.5+dV*0.25+cell*0.1+dW*0.1+feedback;
  const v=blend*0.5+0.5;
  const pal=[[6,10,48],[14,38,82],[18,82,112],[28,148,138],[75,178,130],[195,195,70],[230,160,52],[200,88,58],[135,38,62],[60,18,68],[6,10,48]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i,sf=f*f*(3-2*f);
  const lum=0.78+Math.sin(reaction*Math.PI)*0.22;
  const edge=Math.abs(reaction)>0.62?1.14:1.0;
  const glow=Math.max(0,1-Math.abs(reaction)*1.6)*0.18;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge+glow*45)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge+glow*65)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge+glow*85)|0)
  ];
}
